package com.bare.folders.task;
public final class FolderBackupResult {
 public enum Kind{FAILURE,NO_CHANGE,SUCCESS} private final Kind kind;private final String message;private final Object manifestFile,backupFile;private final long filesScanned,filesAdded,filesModified,filesDeleted,bytes,durationMs;
 public FolderBackupResult(Kind k,String m,Object mf,Object bf,long scanned,long added,long modified,long deleted,long bytes,long duration){if(k==null)throw new IllegalArgumentException("kind");kind=k;message=m;manifestFile=mf;backupFile=bf;filesScanned=Math.max(0,scanned);filesAdded=Math.max(0,added);filesModified=Math.max(0,modified);filesDeleted=Math.max(0,deleted);this.bytes=Math.max(0,bytes);durationMs=Math.max(0,duration);}
 public Kind getKind(){return kind;}public String getMessage(){return message;}public Object getManifestFile(){return manifestFile;}public Object getBackupFile(){return backupFile;}public long getFilesScanned(){return filesScanned;}public long getFilesAdded(){return filesAdded;}public long getFilesModified(){return filesModified;}public long getFilesDeleted(){return filesDeleted;}public long getBytes(){return bytes;}public long getDurationMs(){return durationMs;}
}